UPDATE pm_artifact SET how_to = '["List the problem you''re evaluating","Score on Unworkable (broken process?), Unavoidable (must solve?), Urgent (right now?), Underserved (no good solution?)","Problems scoring high on all 4 are worth pursuing","Use to prioritize which problems to solve first"]'::jsonb WHERE name = '4U Framework' AND how_to = '[]'::jsonb;
